def transform(grid):
    h,w=len(grid),len(grid[0]); seen=set(); n=0
    for r in range(h):
        for c in range(w):
            if grid[r][c]==0 or (r,c) in seen: continue
            n+=1; color=grid[r][c]; stack=[(r,c)]; seen.add((r,c))
            while stack:
                a,b=stack.pop()
                for x,y in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
                    if 0<=x<h and 0<=y<w and (x,y) not in seen and grid[x][y]==color:
                        seen.add((x,y)); stack.append((x,y))
    return [[0]*n]

